const fs = require('fs');
const path = require('path');
const compiler = require('vue-template-compiler');
const dir = 'zhi2-web-admin/src/views/property/marketMonitor/components';
const files = ['MarketHeader.vue','KpiCards.vue','DistrictPie.vue'];
let ok = true;
for (const f of files) {
  const full = path.join(dir, f);
  const src = fs.readFileSync(full, 'utf8');
  const parsed = compiler.parseComponent(src);
  const res = compiler.compile(parsed.template.content);
  if (res.errors && res.errors.length) {
    ok = false;
    console.log(`TEMPLATE ERRORS in ${f}:`);
    console.log(res.errors);
  } else {
    console.log(`${f}: template OK (tips=${res.tips ? res.tips.length : 0})`);
  }
}
process.exit(ok ? 0 : 1);

const fs=require('fs'),path=require('path'),compiler=require('vue-template-compiler');
const dir='zhi2-web-admin/src/views/property/marketMonitor/components';
for(const f of ['MarketHeader.vue','KpiCards.vue','DistrictPie.vue']){
  const src=fs.readFileSync(path.join(dir,f),'utf8');
  const p=compiler.parseComponent(src);
  let code=p.script.content.replace(/^\s*import[^\n]*\n/gm,'').replace(/export default/,'const __c =');
  try{ new Function(code); console.log(f+': script OK'); }
  catch(e){ console.log(f+': SCRIPT ERROR '+e.message); process.exitCode=1; }
}
